export function getGOSPELS_CURRICULUMLevel(levelNumber: number): CurriculumLevelData {
  const safeLevel = Math.max(1, Math.min(100, levelNumber));
  return GOSPELS_CURRICULUM_LEVELS[safeLevel - 1];
}
